def binary_search(arr, target):
    lo, hi = 0, len(arr) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if arr[mid] == target:
            return mid
        if arr[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1

func quicksort(a []int) {
    if len(a) < 2 {
        return
    }
    pivot := a[len(a)/2]
    less, equal, greater := []int{}, []int{}, []int{}
    for _, v := range a {
        switch {
        case v < pivot:
            less = append(less, v)
        case v == pivot:
            equal = append(equal, v)
        default:
            greater = append(greater, v)
        }
    }
    quicksort(less)
    quicksort(greater)
    copy(a, append(append(less, equal...), greater...))
}

from collections import deque

def bfs(graph, start):
    visited = {start}
    q = deque([start])
    order = []
    while q:
        node = q.popleft()
        order.append(node)
        for neighbour in graph[node]:
            if neighbour not in visited:
                visited.add(neighbour)
                q.append(neighbour)
    return order

fn merge_sort(v: Vec<i32>) -> Vec<i32> {
    if v.len() <= 1 {
        return v;
    }
    let mid = v.len() / 2;
    let left = merge_sort(v[..mid].to_vec());
    let right = merge_sort(v[mid..].to_vec());
    let (mut i, mut j, mut out) = (0, 0, Vec::with_capacity(v.len()));
    while i < left.len() && j < right.len() {
        if left[i] <= right[j] {
            out.push(left[i]); i += 1;
        } else {
            out.push(right[j]); j += 1;
        }
    }
    out.extend_from_slice(&left[i..]);
    out.extend_from_slice(&right[j..]);
    out
}

